-- SINH TỰ ĐỘNG bởi scripts/generate_seed.py từ mock JSON. Không sửa tay.

on conflict (category, code) do update set label_vi = excluded.label_vi, sort_order = excluded.sort_order, color_hex = excluded.color_hex, sf_symbol = excluded.sf_symbol, attributes = excluded.attributes, center = excluded.center;





on conflict (code) do update set geom = excluded.geom, is_mock = excluded.is_mock, source_url = excluded.source_url, verified_at = excluded.verified_at;


